//! Parity and regression tests for the soprano family.
//!
//! Pinned fixtures reside in `testdata/tts_soprano/`, generated by
//! `tools/gen_soprano_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference modules (text.py clean_text,
//! `Model._preprocess_text`, `SopranoDecoder`, and the
//! `stream_generate` loop through `Model.generate` with a deterministic
//! offline tokenizer mock) against a tiny seeded qwen3 + decoder, so the
//! traces carry the reference text pipeline, decoder waveform, and
//! greedy end-to-end outputs.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::{clean_text, GenerateParams, Model, StopReason};

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_soprano")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum differences against the fixture traces when the
/// gates were frozen; assertions use these values, not re-measured ones.
/// The decoder waveform matches at 1.4e-7 and the end-to-end generate
/// waveforms at 6.6e-7 (conv accumulation order and FFT plans); the
/// text pipeline, prompt pieces, and generated token ids are exact.
const WAVEFORM_TOLERANCE: f32 = 2e-6;

#[test]
fn clean_text_matches_the_reference_cases() {
    let traces = read_json(&testdata("text/traces.json"));
    for case in traces["clean_cases"].as_array().expect("cases") {
        let got = clean_text(case["input"].as_str().expect("input"));
        assert_eq!(
            got,
            case["output"].as_str().expect("output"),
            "case {}",
            case["name"]
        );
    }
}

#[test]
fn preprocess_text_matches_the_reference_pieces() {
    let traces = read_json(&testdata("text/traces.json"));
    for case in traces["preprocess_cases"].as_array().expect("cases") {
        let got = Model::preprocess_text(
            case["input"].as_str().expect("input"),
            case["min_length"].as_u64().expect("min_length") as usize,
        );
        let want: Vec<String> = case["prompts"]
            .as_array()
            .expect("prompts")
            .iter()
            .map(|v| v.as_str().expect("prompt").to_owned())
            .collect();
        assert_eq!(got, want, "case {}", case["name"]);
    }
}

fn generate_model() -> Model {
    Model::open(&testdata("generate")).expect("family model loads")
}

#[test]
fn family_config_reads_defaults_and_the_pre_1_1_override() {
    let model = generate_model();
    assert_eq!(model.config.sample_rate, 32000);
    assert_eq!(model.config.decoder.decoder_dim, 16);
    assert_eq!(model.config.decoder.token_size, 32);
    // Defaults without a nested decoder_config.
    let defaults = super::ModelConfig::from_json(&serde_json::json!({
        "model_type": "qwen3",
        "hidden_size": 8,
        "num_hidden_layers": 1,
        "intermediate_size": 8,
        "num_attention_heads": 2,
        "num_key_value_heads": 2,
        "head_dim": 4,
        "rms_norm_eps": 1e-5,
        "vocab_size": 8,
        "max_position_embeddings": 64,
        "rope_theta": 1000000.0,
        "tie_word_embeddings": true,
    }))
    .unwrap();
    assert_eq!(defaults.sample_rate, super::DEFAULT_SAMPLE_RATE);
    assert_eq!(defaults.decoder.decoder_dim, 768);
    assert_eq!(defaults.decoder.decoder_intermediate_dim, 2304);
    assert_eq!(defaults.decoder.input_kernel, 1);
    assert_eq!(defaults.decoder.token_size, 2048);
    // Pre-1.1 model_path override.
    let overridden = super::ModelConfig::from_json(&serde_json::json!({
        "model_type": "qwen3",
        "hidden_size": 8,
        "num_hidden_layers": 1,
        "intermediate_size": 8,
        "num_attention_heads": 2,
        "num_key_value_heads": 2,
        "head_dim": 4,
        "rms_norm_eps": 1e-5,
        "vocab_size": 8,
        "max_position_embeddings": 64,
        "rope_theta": 1000000.0,
        "tie_word_embeddings": true,
        "model_path": "/models/Soprano-80M",
    }))
    .unwrap();
    assert_eq!(overridden.decoder.decoder_dim, 512);
    assert_eq!(overridden.decoder.decoder_intermediate_dim, 1536);
    assert_eq!(overridden.decoder.input_kernel, 3);
    // The 1.1 path keeps the nested geometry.
    let kept = super::ModelConfig::from_json(&serde_json::json!({
        "model_type": "qwen3",
        "hidden_size": 8,
        "num_hidden_layers": 1,
        "intermediate_size": 8,
        "num_attention_heads": 2,
        "num_key_value_heads": 2,
        "head_dim": 4,
        "rms_norm_eps": 1e-5,
        "vocab_size": 8,
        "max_position_embeddings": 64,
        "rope_theta": 1000000.0,
        "tie_word_embeddings": true,
        "model_path": "/models/Soprano-1.1-80M",
        "decoder_config": {"decoder_dim": 768},
    }))
    .unwrap();
    assert_eq!(kept.decoder.decoder_dim, 768);
    assert_eq!(kept.decoder.input_kernel, 1);
}

#[test]
fn decoder_matches_the_reference_waveform() {
    let traces = read_json(&testdata("decoder/traces.json"));
    let model = generate_model();
    let hidden = f32_vec(&traces["hidden"]);
    let positions = traces["positions"].as_u64().expect("positions") as usize;
    let got = model.decoder.forward(&hidden, positions).expect("decodes");
    let want = f32_vec(&traces["waveform"]);
    assert_eq!(got.len(), want.len());
    let diff = max_abs_diff(&got, &want);
    assert!(diff <= WAVEFORM_TOLERANCE, "decoder waveform diff {diff}");
}

#[test]
fn greedy_generation_matches_the_reference_end_to_end() {
    let traces = read_json(&testdata("generate/traces.json"));
    let mut model = generate_model();
    for scenario in traces["scenarios"].as_array().expect("scenarios") {
        let prompt = i32_vec(&scenario["prompt"]);
        let mut params = GenerateParams {
            temperature: 0.0,
            top_p: 0.95,
            max_tokens: scenario["max_tokens"].as_u64().expect("max_tokens") as usize,
            stop_token_ids: i32_vec(&scenario["stop_token_ids"]),
        };
        let _ = &mut params;
        let got = model
            .generate_from_prompt(&prompt, &params, 0)
            .unwrap_or_else(|error| panic!("scenario {} failed: {error}", scenario["name"]));
        assert_eq!(
            got.tokens,
            i32_vec(&scenario["generated"]),
            "scenario {} tokens",
            scenario["name"]
        );
        let want_stopped = scenario["stopped_by"].as_str().expect("stopped_by");
        match (want_stopped, got.stopped_by) {
            ("stop_token", StopReason::StopToken) | ("max_tokens", StopReason::MaxTokens) => {}
            _ => panic!(
                "scenario {} stopped by {:?}",
                scenario["name"], got.stopped_by
            ),
        }
        let want_wave = f32_vec(&scenario["waveform"]);
        assert_eq!(
            got.samples.len(),
            want_wave.len(),
            "scenario {} length",
            scenario["name"]
        );
        let diff = max_abs_diff(&got.samples, &want_wave);
        assert!(
            diff <= WAVEFORM_TOLERANCE,
            "scenario {} waveform diff {diff}",
            scenario["name"]
        );
    }
}

#[test]
fn generate_refuses_an_empty_prompt() {
    let mut model = generate_model();
    let error = model
        .generate_hidden(
            &[],
            &GenerateParams {
                temperature: 0.0,
                ..GenerateParams::default()
            },
            0,
        )
        .unwrap_err();
    assert!(error.to_string().contains("empty prompt"), "{error}");
}

#[test]
fn sampled_path_runs_and_stops_with_the_shared_sampler() {
    // The threefry draw is crate-local, so this checks the mechanism
    // (temperature > 0 filters and samples, stop ids still fire), not
    // reference ids.
    let traces = read_json(&testdata("generate/traces.json"));
    let scenario = &traces["scenarios"]
        .as_array()
        .expect("scenarios")
        .iter()
        .find(|s| s["name"] == "late_stop")
        .expect("late_stop scenario")
        .clone();
    let prompt = i32_vec(&scenario["prompt"]);
    let mut model = generate_model();
    let params = GenerateParams {
        temperature: 0.7,
        top_p: 0.95,
        max_tokens: 64,
        stop_token_ids: i32_vec(&scenario["stop_token_ids"]),
    };
    let got = model.generate_from_prompt(&prompt, &params, 7).unwrap();
    assert!(
        !got.tokens.is_empty() && got.tokens.len() <= 64,
        "sampled token count {}",
        got.tokens.len()
    );
}

#[test]
fn oversized_dollar_amounts_are_not_spoken_as_zero() {
    // u64 overflow used to parse to 0 and read as "zero dollars".
    let got = clean_text("$99999999999999999999");
    assert!(!got.contains("zero"), "{got}");
    assert!(got.contains("99999999999999999999"), "{got}");
    // Normal amounts keep the word form.
    assert!(
        clean_text("$5").contains("five dollars"),
        "{}",
        clean_text("$5")
    );
}
